{
  "representation_type": "resolvent_Hilbert_identity_difference_expression",
  "latent_object": "univariate rational resolvent kernel R(x)=1/(a-x) evaluated at two real points z and w",
  "member_maps": [
    {
      "source_node_id": "G0001",
      "role": "catalog_expression_instance_of_resolvent_Hilbert_identity_difference"
    }
  ],
  "operators": [
    {
      "id": "O1",
      "name": "resolvent_kernel",
      "spec": "x -> 1/(a-x)"
    },
    {
      "id": "O2",
      "name": "difference_quotient",
      "spec": "(f(z)-f(w))/(z-w)"
    },
    {
      "id": "O3",
      "name": "multiplication",
      "spec": "(u,v) -> u*v"
    }
  ],
  "reconstruction_rule": "Apply O2 to O1 to form the first term; apply O3 to O1(z) and O1(w) to form the second term; subtract the second term from the first. This yields G0001.",
  "required_assumptions": [
    "a, z, w are real",
    "z != w",
    "a != z",
    "a != w"
  ],
  "proof_obligations": [
    "Show that O2(O1) and O3(O1(z), O1(w)) are algebraically equivalent by simplifying the numerator of O2(O1).",
    "Verify that the domain constraints z != w, a != z, a != w are sufficient for all denominator terms in G0001 to be defined."
  ]
}
